from flask import Blueprint, request, jsonify
from app.models.problem import Problem
from app.database import db

def problem_blueprint():
    blueprint = Blueprint('problems', __name__)

    @blueprint.route('/problems', methods=['GET'])
    def get_problems():
        try:
            problems = Problem.query.all()
            result = [problem.to_dict() for problem in problems]
            return jsonify(result), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/problems/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404
            return jsonify(problem.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/problems', methods=['POST'])
    def create_problem():
        try:
            data = request.json
            new_problem = Problem(**data)
            db.session.add(new_problem)
            db.session.commit()
            return jsonify(new_problem.to_dict()), 201
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @blueprint.route('/problems/<int:problem_id>', methods=['PUT'])
    def update_problem(problem_id):
        try:
            data = request.json
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404

            for key, value in data.items():
                setattr(problem, key, value)

            db.session.commit()
            return jsonify(problem.to_dict()), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 400

    @blueprint.route('/problems/<int:problem_id>', methods=['DELETE'])
    def delete_problem(problem_id):
        try:
            problem = Problem.query.get(problem_id)
            if not problem:
                return jsonify({'error': 'Problem not found'}), 404

            db.session.delete(problem)
            db.session.commit()
            return jsonify({'message': 'Problem deleted successfully'}), 200
        except Exception as e:
            db.session.rollback()
            return jsonify({'error': str(e)}), 500

    return blueprint

from flask import Blueprint, request, jsonify
from app.models.user import User
from app.database import db

def user_blueprint():
    blueprint = Blueprint('user', __name__)

    @blueprint.route('/user', methods=['GET'])
    def get_users():
        try:
            users = User.query.all()
            return jsonify([user.to_dict() for user in users]), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/user', methods=['POST'])
    def create_user():
        try:
            data = request.json
            username = data.get('username')
            email = data.get('email')

            if not username or not email:
                return jsonify({'error': 'Missing username or email'}), 400

            new_user = User(username=username, email=email)
            db.session.add(new_user)
            db.session.commit()

            return jsonify(new_user.to_dict()), 201
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/user/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404

            return jsonify(user.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/user/<int:user_id>', methods=['PUT'])
    def update_user(user_id):
        try:
            data = request.json
            user = User.query.get(user_id)

            if not user:
                return jsonify({'error': 'User not found'}), 404

            username = data.get('username')
            email = data.get('email')

            if username:
                user.username = username
            if email:
                user.email = email

            db.session.commit()
            return jsonify(user.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    @blueprint.route('/user/<int:user_id>', methods=['DELETE'])
    def delete_user(user_id):
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404

            db.session.delete(user)
            db.session.commit()
            return jsonify({'message': 'User deleted successfully'}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 500

    return blueprint

from flask import Blueprint, request, jsonify
from app.models.solution import Solution
from app.database import db

def solution_blueprint():
    blueprint = Blueprint('solution', __name__)

    @blueprint.route('/solutions', methods=['POST'])
    def submit_solution():
        try:
            data = request.get_json()
            code = data.get('code')
            problem_id = data.get('problem_id')
            user_id = data.get('user_id')

            if not code or not problem_id or not user_id:
                return jsonify({"error": "Missing required fields"}), 400

            solution = Solution(code=code, problem_id=problem_id, user_id=user_id)
            db.session.add(solution)
            db.session.commit()

            return jsonify({"message": "Solution submitted successfully", "solution_id": solution.id}), 201
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @blueprint.route('/solutions/<int:solution_id>', methods=['GET'])
    def get_solution(solution_id):
        try:
            solution = Solution.query.get(solution_id)
            if not solution:
                return jsonify({"error": "Solution not found"}), 404

            return jsonify({
                "id": solution.id,
                "code": solution.code,
                "problem_id": solution.problem_id,
                "user_id": solution.user_id,
                "created_at": solution.created_at
            }), 200
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    return blueprint
